    [3, 6, 3, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 3, 6, 3, 6, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 3, 6, 6, 6, 6, 3, 6, 6, 3, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 6, 6, 3, 6, 6, 6, 6, 6, 6, 6, 3, 6, 6, 6, 6, 6],
    [6, 6, 3, 6, 6, 6, 6, 6, 6, 6, 6, 3, 6, 6, 6, 6, 6, 6, 6, 3],
    [3, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 3, 6, 6],
    [6, 6, 6, 6, 6, 3, 6, 6, 6, 6, 6, 6, 6, 3, 6, 3, 6, 6, 6, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 3, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
    [6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6],
]

markers = []
for r, row in enumerate(grid):
    for c, val in enumerate(row):
        if val != 6:
            markers.append((r, c, val))

# Look at columns where markers appear
print("Column frequency:")
col_counts = {}
for r, c, v in markers:
    if c not in col_counts:
        col_counts[c] = []
    col_counts[c].append((r, v))

for c in sorted(col_counts.keys()):
    print(f"Col {c}: {len(col_counts[c])} markers at rows {[x[0] for x in col_counts[c]]}")

# Look for any adjacent markers in same column (vertical pairs/triplets)
print("\nVertical adjacency analysis:")
for col, data in col_counts.items():
    data.sort(key=lambda x: x[0])
    runs = []
    current_run = [data[0]]
    for i in range(1, len(data)):
        if data[i][0] == data[i-1][0] + 1:
            current_run.append(data[i])
        else:
            if len(current_run) >= 2:
                runs.append(current_run)
            current_run = [data[i]]
    if len(current_run) >= 2:
        runs.append(current_run)

    if runs:
        print(f"Col {col} has vertical runs: {runs}")

# Look at rows where markers appear
print("\nRow frequency:")
row_counts = {}
for r, c, v in markers:
    if r not in row_counts:
        row_counts[r] = []
    row_counts[r].append((c, v))

for r in sorted(row_counts.keys()):
    print(f"Row {r}: {len(row_counts[r])} markers at cols {[x[0] for x in row_counts[r]]}")

# Look for floor patterns - rows with consecutive markers
print("\nHorizontal adjacency analysis:")
for row, data in row_counts.items():
    data.sort(key=lambda x: x[0])
    runs = []
    current_run = [data[0]]
    for i in range(1, len(data)):
        if data[i][0] == data[i-1][0] + 1:
            current_run.append(data[i])
        else:
            if len(current_run) >= 2:
                runs.append(current_run)
            current_run = [data[i]]
    if len(current_run) >= 2:
        runs.append(current_run)

    if runs:
        print(f"Row {row} has horizontal runs: {runs}")

